Path('android-native/app/src/main/java/com/ozbiltar/yonetim/NotificationReceiver.java').write_text('''package com.ozbiltar.yonetim;\nimport android.app.*; import android.content.*; import android.os.Build;\npublic class NotificationReceiver extends BroadcastReceiver { public void onReceive(Context context, Intent intent){ String title=intent.getStringExtra("title"), body=intent.getStringExtra("body"); int id=intent.getIntExtra("id",1); NotificationManager nm=(NotificationManager)context.getSystemService(Context.NOTIFICATION_SERVICE); if(Build.VERSION.SDK_INT>=Build.VERSION_CODES.O)nm.createNotificationChannel(new NotificationChannel("ozbiltar_reminders","ÖZBİLTAR Hatırlatıcıları",NotificationManager.IMPORTANCE_HIGH)); Intent open=new Intent(context,MainActivity.class); open.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP); int flags=PendingIntent.FLAG_UPDATE_CURRENT; if(Build.VERSION.SDK_INT>=Build.VERSION_CODES.M)flags|=PendingIntent.FLAG_IMMUTABLE; PendingIntent pi=PendingIntent.getActivity(context,id,open,flags); Notification.Builder b=Build.VERSION.SDK_INT>=Build.VERSION_CODES.O?new Notification.Builder(context,"ozbiltar_reminders"):new Notification.Builder(context); b.setSmallIcon(R.mipmap.ic_launcher).setContentTitle(title==null?"ÖZBİLTAR":title).setContentText(body==null?"Hatırlatıcı":body).setStyle(new Notification.BigTextStyle().bigText(body)).setContentIntent(pi).setAutoCancel(true); nm.notify(id,b.build()); }}\n''')
